import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"공통적 의견","slug":"공통적-의견","link":"#공통적-의견","children":[]},{"level":2,"title":"불교의 한반도 유입","slug":"불교의-한반도-유입","link":"#불교의-한반도-유입","children":[]},{"level":2,"title":"원효의 삶과 문제의식","slug":"원효의-삶과-문제의식","link":"#원효의-삶과-문제의식","children":[]},{"level":2,"title":"원효의 일심·화쟁 사상","slug":"원효의-일심·화쟁-사상","link":"#원효의-일심·화쟁-사상","children":[{"level":3,"title":"1. 각(覺)의 문제","slug":"_1-각-覺-의-문제","link":"#_1-각-覺-의-문제","children":[]},{"level":3,"title":"2. 화쟁(和諍)사상","slug":"_2-화쟁-和諍-사상","link":"#_2-화쟁-和諍-사상","children":[]},{"level":3,"title":"3. 일심이문(一心二門)의 내용","slug":"_3-일심이문-一心二門-의-내용","link":"#_3-일심이문-一心二門-의-내용","children":[]}]}],"relativePath":"philosophy/Korean-Philosophy/04. 원효의 화쟁.md","filePath":"philosophy/Korean-Philosophy/04. 원효의 화쟁.md"}'),l={name:"philosophy/Korean-Philosophy/04. 원효의 화쟁.md"};function e(a,t,g,i,h,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="공통적-의견" tabindex="-1">공통적 의견 <a class="header-anchor" href="#공통적-의견" aria-label="Permalink to &quot;공통적 의견&quot;">​</a></h2><p>언어와 사유가 세계를 분별하고 구분짓게 만듦. 언어는 있는 그대로를 가리고, 그것을 개념화시켜 본질을 보지 못하게 만듦.</p><h2 id="불교의-한반도-유입" tabindex="-1">불교의 한반도 유입 <a class="header-anchor" href="#불교의-한반도-유입" aria-label="Permalink to &quot;불교의 한반도 유입&quot;">​</a></h2><p><strong>고구려</strong></p><ol><li>현실을 중시하는 무속과 마찰 — 기복신앙과 불교 사이의 마찰</li><li>농업 기반의 사회제도와 충돌 — 노동집약적인 농업과 출가 중심의 불교 사이의 충돌<br> → 이후 신라와 일본으로 전파</li></ol><h2 id="원효의-삶과-문제의식" tabindex="-1">원효의 삶과 문제의식 <a class="header-anchor" href="#원효의-삶과-문제의식" aria-label="Permalink to &quot;원효의 삶과 문제의식&quot;">​</a></h2><p>신라의 삼국통일 시기에 활동. 10대에 출가해 여러 공부를 했으나 학문적 열정이 충족되지 않음. 30대에 유학을 가려다 고구려에서 문제가 생겨 가지 못했고, 40대에 당으로 가려던 도중 다시 문제가 생김.</p><p>유학길 도중 동굴에서 해골물을 마시고 동굴과 무덤이 둘이 아님을 깨닫고 유학을 포기함. 요석공주와 혼인해 설총을 낳고 대중교화에 힘쓰다, 다시 사원으로 돌아와 생을 마감함.</p><p>원효는 100여 종 240여 권(혹은 85종 170여 권)에 이르는 방대한 저술을 남겼다고 전해지나 현존하는 것은 19부 22권뿐이다. 대표작은 『대승기신론소』·『대승기신론별기』(중관과 유식을 화합시켜 <strong>진속불이</strong>·<strong>일심이문</strong>을 밝힘), 『금강삼매경론』(본각과 시각을 핵심으로 삼음), 『십문화쟁론』(백가의 서로 다른 쟁론을 화해시켜 일미의 법해로 돌아가게 함)이다. 원효의 문제의식은 크게 세 갈래로 요약된다 — <strong>불교의 토착화</strong>, <strong>민중 중심 불교</strong>, 그리고 <strong>화쟁 불교</strong>.</p><h2 id="원효의-일심·화쟁-사상" tabindex="-1">원효의 일심·화쟁 사상 <a class="header-anchor" href="#원효의-일심·화쟁-사상" aria-label="Permalink to &quot;원효의 일심·화쟁 사상&quot;">​</a></h2><h3 id="_1-각-覺-의-문제" tabindex="-1">1. 각(覺)의 문제 <a class="header-anchor" href="#_1-각-覺-의-문제" aria-label="Permalink to &quot;1. 각(覺)의 문제&quot;">​</a></h3><p><strong>각이란 무엇인가?</strong> 원효는 깨달음(覺)을 <strong>본각(本覺)</strong>과 <strong>시각(始覺)</strong> 두 가지로 나눈다.</p><ul><li><strong>본각</strong>: 마음의 본성 자체가 지닌 지혜의 광명. 마음의 본성이 애초부터 불각(不覺)의 모습을 떠나 있어, 그 자체가 이미 깨닫고 비추는 성품이라는 뜻에서 붙은 이름이다.</li><li><strong>시각</strong>: 이 본각이 무명(無明)의 인연을 따라 흔들려 망념을 일으키지만, 본각이 스스로를 훈습(薰習)하는 힘에 의지해 점차 깨달음의 작용이 생겨나 마침내 본각과 다시 하나가 되는 과정을 가리킨다.</li></ul><p>즉 중생의 마음은 본래 지혜의 광명(본각)이지만 무명에 가려져 있을 뿐이며, 그 광명이 끊임없이 스스로를 훈습해 처음의 깨달음(시각)을 일으키고 마침내 본래의 깨달음과 합일한다.</p><p><strong>각에 이르는 길</strong>: 원효는 이 과정을 여섯 문(門)으로 정리한다. 앞의 넷은 실천을 통해 마음을 준비시키는 <strong>행문(行門)</strong>이다 — ①<strong>보시문</strong>(비움과 베풂, 자비와 연기적 감수성의 확대), ②<strong>지계문</strong>(계율을 지켜 선정의 기반을 마련함), ③<strong>인욕문</strong>(욕됨을 참아 무아의 통찰을 도움), ④<strong>정진문</strong>(수행에 힘써 선근을 지속·성장시킴). 그리고 다섯째 ⑤<strong>지관문(止觀門)</strong>은 마음을 가라앉혀 산란을 멈추고(止, 선정) 동시에 바로 비추어 보아(觀, 지혜) 일심을 통찰하는 문으로, 앞의 행문들이 지향하는 최종 단계에 해당한다. (이는 『반야경』의 6바라밀 — 보시·지계·인욕·정진·선정·지혜 — 을 원효 나름으로 재구성한 것이다.)</p><h3 id="_2-화쟁-和諍-사상" tabindex="-1">2. 화쟁(和諍)사상 <a class="header-anchor" href="#_2-화쟁-和諍-사상" aria-label="Permalink to &quot;2. 화쟁(和諍)사상&quot;">​</a></h3><p>원효가 활동하던 시기 불교는 이미 섭론종·구사종·지론종·법상종·천태종·삼론종·화엄종 등 수많은 각론(各論)으로 갈라져 있었다. 아리안 문명과 인더스 문명이 결합해 브라만교가 성립하고, 그로부터 초기불교 — 부파불교(상좌부·대중부) — 대승불교 — 중관(공사상) — 유식으로 이어지는 불교사 자체가 이미 해석과 계율을 둘러싼 분파와 논쟁의 역사였다. 원효는 이 갈라진 목소리들을 다시 하나로 회통시키고자 했다.</p><blockquote><p>&quot;만법(萬法)이 일불승(一佛乘)에 총섭(總攝)되어야 하는 것은 마치 대해(大海)에 온갖 물이 흘러들어가지 않는 것이 없는 것과 같다.&quot;(『금강삼매경론』)</p><p>&quot;뭇 경전의 부분적인 면을 통합하여 온갖 물줄기를 한 맛의 진리 바다로 돌아가게 하고, 불교의 지극히 공변된 뜻을 모든 사상가들의 서로 다른 쟁론을 화해시킨다.&quot;(『열반경종요』)</p></blockquote><p>즉 소승과 대승, 중관과 유식, 돈오와 점수 등 서로 다른 가르침·수행·법문은 결국 <strong>일불승</strong>(하나의 부처의 길) 속에 포괄·수렴된다는 것이다. 수많은 강물과 샘과 빗물이 결국 모두 큰 바다로 흘러들어가듯, 어느 것도 빠짐없이 일불승으로 합해진다.</p><p><strong>화쟁의 논리</strong>는 크게 세 단계로 작동한다. ①<strong>개합(開合)</strong>: 하나의 뜻을 펼쳐서(開) 여러 갈래로 설명하기도 하고, 다시 그것을 모아서(合) 하나로 회통시키기도 함으로써 서로 통하는 지점을 이끌어낸다. ②<strong>입파(立破)와 여탈(與奪)</strong>: 각 주장을 세우기도(立) 깨뜨리기도(破) 하면서, 그 과정에서 받아들일 수 있는 부분과 받아들일 수 없는 부분을 가려낸다. ③<strong>종요(宗要)</strong>: 이 개합·입파의 과정을 거쳐 마지막으로 여러 주장을 관통하는 공통의 원리를 세운다. 이 모든 과정에서 원효가 견지하는 태도는 <strong>비유비무(非有非無)</strong>·<strong>비동비이(非同非異)</strong> — 있음도 아니고 없음도 아니며, 같음도 아니고 다름도 아니라는 것이다. 어느 한쪽 극단에 서서 다른 쪽을 전면 부정하지 않고, 각 주장이 나름의 맥락에서 타당성을 갖는 지점을 인정하면서 그것들을 꿰뚫는 원리를 찾아낸다.</p><h3 id="_3-일심이문-一心二門-의-내용" tabindex="-1">3. 일심이문(一心二門)의 내용 <a class="header-anchor" href="#_3-일심이문-一心二門-의-내용" aria-label="Permalink to &quot;3. 일심이문(一心二門)의 내용&quot;">​</a></h3><p>화쟁이 가능한 근거는 결국 모든 다툼이 <strong>하나의 마음(一心)</strong>에서 비롯된다는 데 있다. 『대승기신론소』는 이 일심에 두 개의 문이 있다고 말한다.</p><blockquote><p>&quot;한마음의 법에 의하여 두 가지 문이 있다. 하나는 <strong>심진여문</strong>이고, 다른 하나는 <strong>심생멸문</strong>이다. 이 두 문은 각각 일체의 법을 총괄하고 있으며, 서로 분리되지 않는다.&quot;(『대승기신론소』)</p></blockquote><ul><li><strong>진여문(眞如門)</strong>: 마음의 본성은 나지도 멸하지도 않으나, 일체의 법은 오직 <strong>망념(妄念)</strong>에 의해서만 차별과 구분이 생긴다. 망념을 여의면 일체의 경계상이 사라지므로, 일체의 법은 본래 언설상·명자상·심연상을 떠나 결국 평등하며 변하지도 파괴되지도 않는 오직 하나의 마음뿐이다 — 그래서 <strong>진여</strong>라 이름한다. 존재의 본체적·이치적 측면(體, 理)을 가리키며, 중관(공)사상과 상응한다.</li><li><strong>생멸문(生滅門, 隨緣門)</strong>: 마음에서 말하는 일체의 사법(事法)은 <strong>의타성(依他性)</strong>에 속한다. 모든 법이 인연화합으로 생멸하기 때문이다. 세간의 온갖 법을 논하는 것은 바로 이 생멸문에 의거한 변별이다. 현상적·작용적 측면(相, 事)을 가리키며, 유식사상과 상응한다.</li></ul><p>두 문은 서로 다른 두 개의 마음이 아니라 <strong>하나의 마음이 지닌 두 측면</strong>이다. 진여문에 의지해 지행(止行, 산란을 그침)을 닦고 생멸문에 의지해 관행(觀行, 실상을 비추어봄)을 일으키니, 지관을 함께 닦으면 만행(萬行)이 갖추어지고 이 두 문에 들어서면 모든 문이 통한다. 중관은 &quot;파(破)하는 길로 들어서니 긍정하는 길이 끊기는&quot; 접근이고, 유식은 &quot;세우는(立) 길에 들어서니 부정할 길이 끊기는&quot; 접근인데, 원효는 이 두 길이 결국 한마음의 두 문으로서 서로 배타적이지 않음을 보인 것이다.</p><p>이러한 일심이문의 관점에서 보면, 생멸문(현상적 측면)에 집착하면 분별이 생겨 좋고 나쁨을 가르게 되고 결국 얻지 못함에서 오는 고통이 발생한다. 그렇다고 &quot;모든 것이 공(空)이다&quot;라는 말을 듣고 아무것도 존재하지 않는다고 여겨서도 안 된다 — 존재의 그릇으로서의 현상은 현상대로 인정해야 한다. <strong>현상은 존재 그 자체는 아니지만(現象≠存在), 현상은 존재가 머무는 집이다.</strong> 이것이 원효가 진여문과 생멸문 그 어느 한쪽에도 치우치지 않는 이유다.</p><p>원효 사상의 이러한 경지는 흔히 다음과 같은 선구(禪句)의 흐름으로 요약되기도 한다 — &quot;산은 산이고 물은 물이다&quot;(분별에 머무는 처음의 앎) → &quot;산은 산이 아니고 물은 물이 아니다&quot;(분별을 깨뜨리는 공의 깨달음) → &quot;산은 산이고 물은 물이다&quot;(공의 깨달음 위에서 다시 현상을 있는 그대로 긍정하는 최종적 화쟁의 경지). 원효가 만년에 소성거사로 저잣거리를 돌아다니며 &quot;일체에 걸림이 없는 사람이 한 길로 생사를 벗어났다&quot;(一切無碍人 一道出生死)고 노래한 것도, 세간과 출세간, 중생과 부처, 민중과 귀족이 둘이 아니라는 화쟁의 정신을 삶으로 실천한 것이라 할 수 있다.</p>',27)])])}const d=o(l,[["render",e]]);export{_ as __pageData,d as default};
